private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor must not be null or empty");
    }

    int index = 0;
    try {
        if (descriptor.charAt(0) == '(') { // Method descriptor
            index = 1;
            while (descriptor.charAt(index) != ')') {
                index = popType(descriptor, index);
            }
            index++; // skip ')'
        }
        // If it's a type descriptor, pop the type
        if (index < descriptor.length()) {
            popType(descriptor, index);
        }
    } catch (Exception e) {
        throw new RuntimeException("Error popping types from the stack based on descriptor: " + descriptor, e);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'V': // void
            break;
        case 'Z': // boolean
        case 'C': // char
        case 'B': // byte
        case 'S': // short
        case 'I': // int
        case 'F': // float
            index += 1;
            break;
        case 'D': // double
        case 'J': // long
            index += 1;
            break;
        case 'L': // class reference
            index = descriptor.indexOf(';', index) + 1;
            break;
        case '[': // array
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            if (descriptor.charAt(index) == 'L') {
                index = descriptor.indexOf(';', index) + 1;
            } else {
                index += 1;
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

private void pop(final String descriptor){
    try {
        if (descriptor == null || descriptor.isEmpty()) {
            return; // No operation if descriptor is null or empty
        }

        // Check if the descriptor is a method descriptor
        if (descriptor.charAt(0) == '(') {
            // Find the end of the argument list
            int endIndex = descriptor.indexOf(')');
            if (endIndex == -1) {
                throw new IllegalArgumentException("Invalid method descriptor");
            }

            // Extract the argument types
            String arguments = descriptor.substring(1, endIndex);
            int current = 0;
            while (current < arguments.length()) {
                char c = arguments.charAt(current);
                switch (c) {
                    case 'B': // byte
                    case 'C': // char
                    case 'D': // double
                    case 'F': // float
