void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and result map must not be null");
    }
    Set<V> leftPartition = new HashSet<>();
    Set<V> rightPartition = new HashSet<>(resultMap.values());

    // Assuming resultMap contains at least two distinct vertices for bipartition
    if (rightPartition.size() < 2) {
        throw new IllegalArgumentException("Result map must contain at least two distinct vertices for bipartition");
    }

    // Split the vertices into two partitions
    Iterator<V> iterator = rightPartition.iterator();
    leftPartition.add(iterator.next());

    // Add all edges between the two partitions
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            if (!leftVertex.equals(rightVertex)) {
                target.addEdge(leftVertex, rightVertex);
            }
        }
    }
}

void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and result map cannot be null");
    }

    Set<V> leftPartition = new HashSet<>();
    Set<V> rightPartition = new HashSet<>(resultMap.values());

    if (rightPartition.size() < 2) {
        // Not enough vertices to form a bipartite graph
        return;
    }

    int index = 0;
    for (String key : resultMap.keySet()) {
        if (leftPartition.size() == rightPartition.size()) {
            break; // Balanced bipartition
        }
        V vertex = resultMap.get(key);
        if (!leftPartition.contains(vertex)) {
            leftPartition.add(vertex);
            rightPartition.remove(vertex);
        }
        index++;
    }

    // Add edges between each vertex in left partition to each vertex in right partition
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

