    }

    V startVertex = null;
    Map<V, V> vertexMap = new HashMap<>();

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            startVertex = source;
        }

        if (vertexMap.containsKey(target)) {
