private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.size() < 2) {
        return true; // A single vertex or empty set is trivially a clique
    }

    for (V vertex : vertices) {
        Set<V> neighbors = new HashSet<>(Graphs.neighborListOf(graph, vertex));
        neighbors.retainAll(vertices);
        if (neighbors.size() != vertices.size() - 1) {
            return false;
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.size() < 2) {
        return true; // A single vertex or null inputs can be considered trivially a clique
    }
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("Vertex " + vertex + " is not in the graph");
        }
    }
    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (!vertex.equals(otherVertex) && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }
    return true;
}

