public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    while (true) {
        if (isPrime(candidate)) {
            if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
                return previousPrime(candidate);
            }
            return candidate;
        }
        candidate += 2;
    }
}

private static boolean isPrime(int number) {
    if (number <= 1) return false;
    if (number <= 3) return true;
    if (number % 2 == 0 || number % 3 == 0) return false;
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) return false;
    }
    return true;
}

private static int previousPrime(int number) {
    if (number < 3) return 2;
    int candidate = (number % 2 == 0) ? number - 1 : number;
    while (candidate > 2) {
        candidate -= 2;
        if (isPrime(candidate)) {
            return candidate;
        }
    }
    return 2;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (!isPrime(candidate)) {
        candidate += 2;
    }
    // Check if the found prime is within 11% of the desired capacity for desiredCapacity >= 1000
    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = previousPrime((int) (desiredCapacity * 1.11));
    }
    return candidate;
}

private static boolean isPrime(int num) {
